import json
from pathlib import Path
root=Path(__file__).resolve().parents[3]
rules=json.loads((root/'estilo-editor/datos/revision-v2/rules.json').read_text())
corpus=json.loads((root/'estilo-editor/datos/revision-v2/corpus.json').read_text())['sources']
sections=[];questions=[];examples={}
for r in rules:
 for i,e in enumerate(r['evidence']):
  key=f'{r["id"]}-{i+1}';s=next(s for s in corpus if s['slug']==e['slug'])
  examples[key]={'id':key,'ruleId':r['id'],'title':e['observation'],'source':s['slug'],'sourceTitle':s['title'].removesuffix('.mp4'),'f0':e['f0'],'f1':e['f1'],'fps':s['fps_num']/s['fps_den'],'sha256':s['source_sha256'],'level':e['level'],'observation':r['observed'],'caution':'Fragmento documentado; su presencia no demuestra que debamos repetirlo en Birdieballs. La intención del editor es una hipótesis.'}
def sec(id,title,intro):sections.append({'id':id,'title':title,'intro':intro})
def q(id,title,opts,refs='',why='',multi=False,scene=None):
 options=[]
 for i,o in enumerate(opts):
  label,_,desc=o.partition('|');options.append({'id':f'o{i+1}','label':label,'description':desc})
 keys=[]
 for key in refs.split():
  if key in examples:keys.append(key)
  else:keys.extend([k for k,v in examples.items() if v['ruleId']==key][:3])
 questions.append({'id':id,'section':sections[-1]['id'],'title':title,'options':options,'type':'multi' if multi else 'single','examples':list(dict.fromkeys(keys)),'ruleIds':list(dict.fromkeys(x.split('-')[0] for x in refs.split())),'why':why,'scene':scene})
sec('referencias','01 · Tus referencias','Valora cada vídeo por separado. Puedes copiar su tipografía sin querer sus gráficos. Las tres versiones ADS 90 pertenecen a una misma familia: no son tres pruebas independientes.')
for s in corpus:
 keys=[k for k,v in examples.items() if v['source']==s['slug']]
 if not keys:
  key='REF-'+s['slug'];examples[key]={'id':key,'ruleId':'G07','title':'Texto sobre el estudio y los personajes','source':s['slug'],'sourceTitle':s['title'].removesuffix('.mp4'),'f0':1450,'f1':1550,'fps':s['fps_num']/s['fps_den'],'sha256':s['source_sha256'],'level':'qualitative_raw_pair','observation':'El estudio y los personajes ya aparecen en el bruto; la tipografía se añade.','caution':'Par bruto/editado revisado cualitativamente; alineación exacta pendiente.'};keys=[key]
 q('ref-'+s['slug'],s['title'].removesuffix('.mp4'),['Referencia principal|Quiero que guíe la dirección de Birdieballs.','Solo algunos recursos|Especifico abajo qué copiar y qué evitar.','No para este anuncio|Puede ser buena edición sin encajar aquí.'],' '.join(keys[:3]),'En el reproductor puedes ver el tramo o liberar el vídeo completo. Anota lo que sí y lo que no; no se interpretará como aprobación global.')
sec('direccion','02 · Dirección y prioridades','Ya están fijados: conservar montaje y voz originales, trabajar este bloque de ~20 s, recuperar SF Pro y retirar los tratamientos rechazados de V04. Aquí defines el carácter de la nueva edición.')
q('tono','¿Qué carácter debe dominar?',['Publicidad de producto cuidada|Precisión, contraste y foco en la bola real.','Humor con edición expresiva|La tipografía participa en el gag.','Impacto tipográfico|Las palabras construyen la mayor parte del espectáculo.','Equilibrio entre humor y producto|Cambiar de registro entre problema y solución.'],'T01 G01 E01','Elegir una dirección limita la mezcla arbitraria de estilos.')
q('prioridades','¿Qué debe mejorar más? Elige hasta tres prioridades.',['Composición de los subtítulos','Variedad de entradas y salidas','Jerarquía y tamaño','Ideas del motion graphic','Materiales, luz y profundidad','Integración con el plano real','Sonido y sincronía'], 'C01 C05 G04','Estas prioridades ordenan las pruebas, sin excluir las demás mejoras.',True)
q('densidad','¿Cuánta presencia debe tener la edición?',['Picos fuertes y descanso|Concentrar el tratamiento en palabras y acciones elegidas.','Presencia frecuente|Composición variable a lo largo de casi cada frase.','Máxima expresividad|Cambios frecuentes, con pausas de lectura.'],'E03 C07 G02','No se interpreta como añadir un efecto cada N segundos.')
q('variacion','¿Cómo quieres variar los recursos?',['Un sistema reconocible, varias construcciones|Cambian composición y movimiento sin cambiar de identidad.','Contrastes claros por escena|Problema, solución y demostración tienen lenguajes distintos.','Variedad amplia|Permitir varios registros, todos ligados al guion.'],'T01 C08 G03')
sec('tipografia','03 · Tipografía','SF Pro vuelve a ser la base por tu indicación. La cursiva de V04 queda descartada; ninguna alternativa está preseleccionada.')
q('peso','¿Qué peso de SF Pro quieres para el texto habitual?',['Regular / Medium|Ligero, con énfasis resuelto por escala y composición.','Semibold|Más presencia sin convertir todo en titular.','Bold|Lectura contundente.','Variable por función|Lectura ligera, palabra clave más pesada.'],'C04 C03','El peso se probará con glifos reales; no se deduce de la caja OCR.')
q('secundaria','¿Qué contraste tipográfico permitirías además de SF Pro?',['Solo SF Pro|Variar tamaño, peso, caja y composición.','Condensada para algún remate|Contraste alto y estrecho como el bloque Jerry de V8.','Otra sans muy distinta|Mostrar pareja concreta antes de animarla.','Proponer pares visuales primero|No introducir otra fuente sin ver la prueba.'],'T01','La serif cursiva usada en V04 no se reutiliza. Estas opciones no aprueban una fuente aún no mostrada.')
q('caja','¿Mayúsculas para qué función?',['Solo gritos o interjecciones','Palabras clave protagonistas','Frases gráficas completas','Preferencia por minúsculas'],'T01 C08',multi=True)
q('tracking','¿Cómo prefieres la densidad de letras?',['Compacta|Tracking ajustado, sin fusionar letras.','Natural|Mantener más aire entre letras.','Depende de la escala|Titulares más compactos que la lectura.'],'C04 C06','El ajuste final depende de los glifos y se comprobará a tamaño móvil.')
q('color-texto','¿Cómo debe usarse el color en los subtítulos?',['Blanco / crema de base y un acento|El acento señala conceptos clave.','Un solo color por bloque|La escala crea la jerarquía.','Color por hablante|Distinguir narrador y personaje.','Alternancia por construcción|Cambiar color al acumular líneas.'],'T02 C08',multi=True)
q('contraste','¿Qué tratamientos de contraste te gustan?',['Sombra pequeña y discreta','Trazo muy fino','Invertir a texto oscuro en fondos claros','Cambiar de posición si mejora el plano','Oscurecer localmente el fondo con sutileza'],'G04 T02','Son recursos permitidos, no capas obligatorias. El tratamiento verde cursivo de «de campos» está descartado.',True)
q('escala','¿Cómo quieres repartir el tamaño?',['Lectura discreta y picos grandes','Lectura mediana y titulares muy grandes','Texto grande casi siempre','Decidir por composición de cada plano'],'C03 M02','Se medirá ancho y altura visible; un mismo cuerpo no produce el mismo tamaño en fuentes distintas.')
sec('composicion','04 · Composición y multilíneas','Separar contenido, jerarquía y posición evita repetir la misma pareja de líneas en cada frase.')
q('fragmentacion','¿Cómo debería dividirse la voz?',['Grupos de sentido cortos|Dos o tres palabras cuando la frase lo permita.','Palabra a palabra|La palabra actual sustituye a la anterior.','Construcción acumulativa|Las palabras forman una composición.','Mezcla por función|Lectura breve y acumulación solo en énfasis.'],'A01 C07 C05')
q('posicion','¿Cuándo cambiar de posición?',['Al cambiar el plano o el espacio disponible','Al cambiar de hablante','Al cambiar de lectura a titular','También dentro de una frase, si el movimiento cuenta algo'],'C01 C08',multi=True)
q('ancla','Dentro de una misma frase, ¿qué se mantiene estable?',['La línea de base|Como pediste para Cansado / de dejarte un.','El centro del conjunto|La composición crece alrededor de un punto.','La palabra protagonista|Los apoyos se organizan a su alrededor.','Elegir un ancla distinta por construcción'],'C01 C06','Tu corrección de alineación sigue vigente: ningún salto accidental entre reemplazos.')
q('multilinea-cuando','¿En qué casos usar varias líneas?',['Contexto pequeño + concepto clave','Frase que se construye progresivamente','Contraste entre dos conceptos','Remate o consecuencia debajo','Evitar multilínea si no aporta jerarquía'],'C05 C07 C08','Seleccionar casos no obliga a aplicarles la misma construcción.',True)
q('multilinea-formas','¿Qué construcciones quieres permitir?',['Apoyo pequeño arriba y núcleo grande','Núcleo grande con remate lateral','Dos bloques enfrentados','Escalera o bloque acumulativo','Texto rodeando un objeto','Una sola línea que cambia de escala'],'C05 C06 A06 C07',multi=True)
q('compactacion','¿Cómo debe sentirse el espacio entre líneas?',['Muy compacto, sin tocarse','Compacto con algo de aire','Contacto óptico controlado|Puede acercarse mucho durante la animación, sin perder lectura.'],'C06','Se medirán cajas de tinta durante la entrada y el asentamiento, no solo line-height.')
q('persistencia','Cuando aparece la palabra clave, ¿qué pasa con el apoyo?',['Permanece hasta completar la idea','Sale para ceder todo el foco','Se recoloca y se reduce','Depende del tipo de frase'],'C05 A07 C07')
q('repeticion','¿Cuándo se puede repetir una construcción?',['Solo si repite una función narrativa','Con variaciones claras de posición y entrada','Reservar cada construcción destacada a un único momento'],'G02 T01','Tu rechazo de las dos multilíneas iguales de V04 queda registrado.')
sec('movimiento','05 · Movimiento del texto','Elige familias que te gustan y dónde tienen sentido. Las referencias muestran diferencias entre aparición, desplazamiento, asentamiento y salida.')
q('entradas','¿Qué entradas quieres en el repertorio?',['Aparición directa','Ascenso que frena sin rebotar','Ascenso con sobrepaso y asentamiento','Desplazamiento lateral','Revelado dentro de máscara','Parpadeo breve en un énfasis'],'A01 A02 A03 A04 G03','No se aplicarán todas a cada frase.',True)
q('funcion-entrada','¿Cómo asignar las entradas?',['Discreta para lectura; expresiva para conceptos','Variar dirección según hueco del plano','Vincularlas a gesto o acción de escena','Un mismo movimiento dentro de cada bloque'],'A01 A03 E01',multi=True)
q('asentamiento','¿Cuánto sobrepaso o elasticidad aceptas?',['Nada|Frenada limpia.','Sutil|Un asentamiento corto casi imperceptible.','Visible en palabras protagonistas|El texto tiene carácter físico.','Elegir tras comparar dos intensidades'],'A02 A03','El ajuste medido de pagar no es una receta universal.')
q('desfase-lineas','¿Cómo deben combinarse las líneas al entrar?',['Contexto primero, palabra clave después','Palabra clave primero, apoyos después','Entradas simultáneas desde posiciones distintas','Una línea se transforma en la siguiente','Alternar según significado'],'C05 A03 C07')
q('salidas','¿Qué salidas permites?',['Reemplazo directo','Desplazamiento fuera del grupo','Desvanecimiento corto','Recorte por máscara','Transformación hacia la palabra siguiente'],'A07 G03','Separa la salida del texto de cualquier corte del metraje, que sigue bloqueado.',True)
q('blur-texto','¿Dónde quieres desenfoque de movimiento?',['Solo en desplazamientos rápidos','En entradas protagonistas y cambios de escala','Muy poco: priorizar nitidez','Comparar intensidad baja y media antes de elegir'],'A05','El blur direccional acompaña velocidad; no equivale a desenfocar todo el texto.')
q('continuidad','¿Cómo debería enlazarse una frase con la siguiente?',['Reemplazos limpios para lectura','Mantener una palabra como ancla','Viajar como grupo y entregar el foco','Mezclar continuidad y cortes tipográficos'],'G03 A07 E02')
sec('profundidad','06 · Texto dentro del plano','Estos tratamientos requieren integración real con el sujeto; no una máscara aproximada sobre la cabeza.')
q('oclusiones','¿Qué capas te gustan?',['Texto frontal nítido','Relleno detrás del sujeto','Relleno detrás + contorno delante','No usar oclusiones en este bloque'],'M01 M02 C02','Elige recursos deseados. «No usar» es excluyente.',True)
q('mascara-frecuencia','¿En cuántos momentos tendría sentido ocultar texto tras el sujeto?',['Un momento protagonista','Varias palabras de un mismo bloque','Solo si el plano lo permite sin forzarlo','Decidir tras un fotograma de prueba'],'M01 M02')
q('texto-curvo','¿Cuándo usar texto curvo o ligado a un objeto?',['Una sola composición protagonista','Cuando siga una forma real del plano','No lo quiero en Birdieballs','Primero ver una propuesta concreta'],'A06 G07','La bombilla de V8 venía en el bruto; el recurso a evaluar aquí es el texto curvo añadido.')
q('integracion','¿Qué otras integraciones aceptarías?',['Perspectiva ligada a una superficie','Texto junto al producto sin taparlo','Foco de luz que dirige la mirada','Recorte del personaje para una composición','Ninguna de estas'],'G06 E01','Los focos y nuevos recortes son propuestas para Birdieballs, no efectos atribuidos sin prueba a las referencias.',True)
sec('motion','07 · Motion graphics','El gráfico de bolas de V04 queda descartado como dirección. Decide qué debe contar el nuevo bloque antes de elegir objetos o cámara.')
q('motion-funcion','¿Qué debería explicar el gráfico principal?',['Recuperar una bola y devolverle valor','Originales de marcas conocidas','Variedad de bolas disponibles','De usado a como nuevo','Prefiero que el metraje real cuente esto'],'G01 G03','La elección debe corresponder a la frase disponible; limpieza/precio aún no se narran en este bloque.')
q('motion-formato','¿Cómo debe convivir con el metraje?',['Gráfico integrado sobre el plano','Composición gráfica a pantalla completa','Transición desde objeto real a escena gráfica','Sin interludio: tipografía protagonista sobre imagen'],'G01 G04 G07','Pantalla completa oculta temporalmente la imagen, pero no cambia sus cortes ni su duración.')
q('motion-metafora','¿Qué tipo de construcción explorar?',['Tipografía que transforma conceptos|Como selección clientes → empleados.','Objetos que se transforman o se relevan|Como reloj → hucha.','Detalle que revela un conjunto|Cambio de escala con una relación clara.','Comparación de estados|Antes/después cuando el guion lo permita.','Sistema de tarjetas o elementos conectados|Solo si hay variedad real que mostrar.'],'G03 G01 G06','Son familias de propuesta, no conceptos originales ya aprobados.',True)
q('motion-material','¿Qué materiales encajan con Birdieballs?',['Producto fotográfico real integrado','Producto 3D con iluminación cuidada','Formas gráficas y tipografía sin bolas flotantes','Combinación de metraje y grafismo','Ver alternativas antes de fijarlo'],'G04 G07','Una imagen 2D girada no se presentará como una bola 3D.')
q('motion-fondo','¿Qué fondo te interesa?',['Estudio claro con sombras y volumen','Oscuro con luz localizada y textura','Material relacionado con golf|Césped, papel o superficie física sin distraer.','Imagen del plano con tratamiento integrado','Ver dos direcciones de arte primero'],'G04','La textura por sí sola no salva una idea débil.')
q('motion-camara','¿Qué movimiento de cámara te interesa?',['Fija y coreografía de objetos','Detalle → conjunto','Recorrido entre elementos','Profundidad con cambio de foco','Combinación con un recorrido principal'],'G03 G04',multi=True)
q('motion-ritmo','¿Qué ritmo debe tener el bloque?',['Una transformación clara con pausa de lectura','Dos o tres beats ligados a la frase','Muy dinámico con cambios frecuentes de foco','Comparar dos duraciones dentro del mismo espacio'],'G02 G03','No se estirará una bola parada para rellenar cinco segundos.')
q('motion-handover','¿Cómo volver al plano real?',['Salida limpia al mismo metraje','Movimiento que entrega el foco a un objeto real','El grafismo se disuelve dejando el plano','Cierre de la composición antes del gag'],'G03 A07','Se conserva el instante original de la acción.')
q('motion-cantidad','Para estos ~20 s, ¿qué estructura te interesa?',['Un bloque protagonista y pequeños acentos','Dos bloques cortos con funciones distintas','Solo efectos integrados sobre el metraje','Decidir tras ver el mapa de la pieza'],'G02 G01','Propuesta de estructura para este anuncio; no periodicidad deducida del corpus.')
q('motion-evitar','¿Qué recursos quieres excluir?',['Bolas flotando como decoración','Iconos genéricos','Flechas explicativas sobre gags','Fondos lisos sin intención','Cambios de escala sin función','Contadores sin una cifra del guion','Tarjetas que aparecen una detrás de otra sin relación'],'G03 G04 E01 G05',multi=True)
